protocol.scriptContent:
// Full Limecoli 384 Assay — 4-Plate Multi-Duration
//
// Plates are loaded from hotel slots and run through:
//   1. Equilibration (10 min)
//   2. OD600 baseline read
//   3. 5 warmup reads
//   4. 3 repetitions of the full illumination sweep:
//      3 durations x 4 colors, each with pre-read, illuminate, post-read, 3 recovery reads
//   5. Return plate to hotel
//
// Plates 1-2 at 25C, plates 3-4 at 37C

var plateNames = [params.plate_name_1, params.plate_name_2, params.plate_name_3, params.plate_name_4];
var assayName = params.assay_name;
var equilibrationSeconds = Number(params.equilibration_seconds) || 600;
var warmupCount = Number(params.warmup_count) || 5;
var recoveryCount = Number(params.recovery_count) || 3;
var repetitions = Number(params.repetitions) || 3;
var durations = [60, 120, 180];

var colors = [
  { name: "Red box",    wavelength: "630nm", transferTo: "transfer-clariostar-to-red-box",    transferFrom: "transfer-red-box-to-clariostar" },
  { name: "Orange box", wavelength: "592nm", transferTo: "transfer-clariostar-to-orange-box", transferFrom: "transfer-orange-box-to-clariostar" },
  { name: "Green box",  wavelength: "525nm", transferTo: "transfer-clariostar-to-green-box",  transferFrom: "transfer-green-box-to-clariostar" },
  { name: "Blue box",   wavelength: "460nm", transferTo: "transfer-clariostar-to-blue-box",   transferFrom: "transfer-blue-box-to-clariostar" },
];

var plates = [
  { plateId: plateNames[0], hotelSlot: 5, temperature: 25 },
  { plateId: plateNames[1], hotelSlot: 4, temperature: 25 },
  { plateId: plateNames[2], hotelSlot: 3, temperature: 37 },
  { plateId: plateNames[3], hotelSlot: 2, temperature: 37 },
];

function read(protocolName, plateId, timepoint) {
  galago.command("Clariostar", "start_read", {
    protocol_name: protocolName,
    plate_id: plateId,
    assay_id: assayName,
    timepoint: timepoint,
  });
}

function loadPlateFromHotel(hotelSlot) {
  galago.command("Clariostar", "open_carrier", {});
  galago.command("Pf400", "run_sequence", { labware: "default", sequence_name: "transfer-hotel-1-slot-" + hotelSlot + "-to-clariostar" });
  galago.command("Clariostar", "close_carrier", {});
}

function returnPlateToHotel(hotelSlot) {
  galago.command("Clariostar", "open_carrier", {});
  galago.command("Pf400", "run_sequence", { labware: "default", sequence_name: "transfer-clariostar-to-hotel-1-slot-" + hotelSlot });
  galago.command("Clariostar", "close_carrier", {});
}

function illuminationCycle(plateId, color, durationSeconds) {
  var suffix = color.wavelength + "_" + durationSeconds + "s";

  // Pre-illumination read
  read("Lime-384-noorbital", plateId, "PreIllumination_" + suffix);

  // Transfer to light box and illuminate
  galago.command("Clariostar", "open_carrier", {});
  galago.command("Pf400", "run_sequence", { labware: "default", sequence_name: color.transferTo });
  galago.command(color.name, "switch", { on: true });
  galago.timer({ minutes: 0, seconds: durationSeconds, message: "Timer in progress..." });
  galago.command("Pf400", "run_sequence", { labware: "default", sequence_name: color.transferFrom });
  galago.command(color.name, "switch", { on: false });
  galago.command("Clariostar", "close_carrier", {});

  // Post-illumination read
  read("Lime-384-noorbital", plateId, "PostIllumination_" + suffix);

  // Recovery reads
  for (var r = 1; r <= recoveryCount; r++) {
    read("Lime-384-noorbital", plateId, "Recovery" + r + "_" + suffix);
  }
}

function runPlateAssay(plate) {
  // Equilibrate
  galago.timer({ minutes: 0, seconds: equilibrationSeconds, message: "Equilibrating plate for " + (equilibrationSeconds / 60) + " minutes..." });

  // OD600 baseline
  read("OD600-384", plate.plateId, "PreAssayOD600");

  // Warmup reads
  for (var w = 1; w <= warmupCount; w++) {
    read("Lime-384-noorbital", plate.plateId, "Warmup" + w);
  }

  // Illumination cycles: repeat the full sweep multiple times
  for (var rep = 0; rep < repetitions; rep++) {
    for (var d = 0; d < durations.length; d++) {
      for (var c = 0; c < colors.length; c++) {
        illuminationCycle(plate.plateId, colors[c], durations[d]);
      }
    }
  }
}

// === Main protocol ===

// Set initial temperature
galago.command("Clariostar", "set_temperature", { temperature: plates[0].temperature });

for (var p = 0; p < plates.length; p++) {
  var plate = plates[p];

  // Change temperature if needed (between plate 2 and 3)
  if (p > 0 && plates[p - 1].temperature !== plate.temperature) {
    galago.command("Clariostar", "set_temperature", { temperature: plate.temperature });
  }

  // Load plate from hotel
  loadPlateFromHotel(plate.hotelSlot);

  // Run the full assay
  runPlateAssay(plate);

  // Return plate to hotel
  returnPlateToHotel(plate.hotelSlot);
}

// Done!
galago.command("Tool Box", "text_to_speech", { text: "Hey hey hey! Your 4-plate limecoli protocol is done done done!" });
